const sql=require("mssql"),mysql=require("mysql2/promise"),CLINIC_ID=1,{getSourceConfig:getSourceConfig}=require("./db.helper"),mssqlConfig=getSourceConfig(),mysqlConfig={host:"127.0.0.1",user:"root",password:"",database:"pozitif_klinik"};async function categorizeData(){let e,t;try{e=await sql.connect(mssqlConfig),t=await mysql.createConnection(mysqlConfig);const i=(await e.request().query("SELECT DISTINCT GELISNO FROM UZM_ICHASTALIKLARI_HST_ANAMNEZ")).recordset.map((e=>e.GELISNO)),o=1e3;for(let e=0;e<i.length;e+=o){const s=i.slice(e,e+o);await t.execute(`UPDATE cln_examinations SET specialty_code = 'IC_HASTALIKLARI' \n                 WHERE legacy_visit_id IN (${s.join(",")}) AND clinic_id = ?`,[1]),process.stdout.write(`\rİşlenen: ${e+s.length}...`)}}catch(e){}finally{e&&await e.close(),t&&await t.end()}}categorizeData();